window.BOREAL.pipeline = {"stages":[{"id":"calibrate","file":"s01_calibrate.py","fig":"calibrate","fa":["کالیبراسیون: مرکز و شعاع‌ها","همه‌ی ساعت از دایره‌های هم‌مرکز ساخته شده. اگر مرکز درست باشد، میانه‌ی روشنایی روی همه‌ی زاویه‌ها (که عقربه‌ها و اعداد را نادیده می‌گیرد) تیزترین پروفایل شعاعی را می‌دهد؛ پس مرکز را با بیشینه‌کردن همین تیزی پیدا می‌کنیم و حلقه‌ها را از روی قله‌های پروفایل می‌خوانیم."],"en":["Calibrate: centre and radii","The whole dial is built from concentric circles. With the right centre, the median over all angles of the radial luminance (which ignores hands and numerals) is razor sharp, so we search for the centre that maximises that sharpness and read every ring off the profile's peaks."],"facts":[{"fa":"مرکز (px)","en":"centre (px)","v":"931.40, 962.84"},{"fa":"شعاع صفحه (px)","en":"dial radius (px)","v":"342.87  (rms 0.542 px)"},{"fa":"حلقه‌ها / R","en":"rings / R","v":"0.2194 · 0.5178 · 0.7156"},{"fa":"عکس دوم (۱۶۰۰px)","en":"second photo (1600 px)","v":"0.2195 · 0.5177 · 0.7163  (coarse peaks; agree with photo 1 within 0.003)"}]},{"id":"edges","file":"s02_edges.py","fig":"edges","fa":["لبه‌یابی","سه آشکارساز مکمل: Canny روی روشنایی (دو مقیاس، اجماع) برای بدنه و بند و دندانه‌ها؛ Canny روی کانال قرمز برای چاپ صفحه (چاپ سفید است و R≈200، صفحه آبی است و R≈10، پس R تقریباً یک نقاشی سیاه‌وسفید است)؛ و گرادیان Scharr برای وزن‌دهی. این‌جا همان لبه‌ها به شکل برداریِ خروجی نمایش داده می‌شود."],"en":["Edge detection","Three complementary detectors: Canny on luminance (two scales, consensus) for case, bracelet and flutes; Canny on the red channel for the dial print (the print is white, R~200, the dial is blue, R~10, so R is almost a black-and-white drawing); and a Scharr gradient for weighting. Here the same edges are shown as the vector output."],"facts":[{"fa":"لبه‌ی روشنایی (px)","en":"luminance edge pixels","v":"76 376"},{"fa":"لبه‌ی چاپ (px)","en":"ink edge pixels","v":"86 493"}]},{"id":"hands","file":"s03_hands.py","fig":"hands","fa":["عقربه‌ها","چاپ نازک است (۳–۸px) و عقربه‌ها ضخیم (≥۲۵px)؛ باز شدن مورفولوژیک با دیسکی بزرگ‌تر از ضخیم‌ترین خط فقط عقربه‌ها را نگه می‌دارد. زاویه با PCA، سپس چرخاندن عکس تا عقربه عمودی شود و خواندن لبه‌ها ردیف‌به‌ردیف با دقت زیرپیکسل. لبه‌ها خط راست‌اند (خطای برازش ≈۰٫۰۵px)."],"en":["Hands","Print is thin (3-8 px) and hands are thick (>= 25 px), so a morphological opening with a disc larger than the thickest stroke keeps only the hands. Angle by PCA, then straighten the photo and read the edges row by row at sub-pixel precision. The edges turn out to be straight lines (fit error ~0.05 px)."],"facts":[{"fa":"زاویه‌ی دقیقه‌شمار","en":"minute hand angle","v":"59.84°"},{"fa":"طول عقربه‌ها (واحد)","en":"lengths (units)","v":"172.1 / 131.7"},{"fa":"ثانیه‌شمار","en":"seconds hand","v":"#D5051F · 6.2 px wide"},{"fa":"مدل نور وجه‌ها","en":"facet light model","v":"F(t)=193.5+53.4·cos(t−120°)"}]},{"id":"primitives","file":"s04_dial_primitives.py","fig":"primitives","fa":["حلقه‌ها، خط‌های دقیقه و پرتوها","در فضای قطبی همه‌چیز محور‌به‌محور می‌شود: حلقه یک خط افقی است (شعاع=مرکز جرم، ضخامت=FWHM)، خطِ دقیقه یک میله‌ی عمودی (زاویه و پهنا)، پرتو یک میله‌ی عمودیِ باریک‌شونده. چیزی که پیدا شد: ۱۲ پرتو هر ۳۰° (نه ۸ تا)، دو ردیف ۶۰تایی خط دقیقه."],"en":["Rings, ticks, rays","In polar space everything becomes axis-aligned: a ring is a horizontal line (radius = centroid, stroke = FWHM), a tick is a vertical bar (angle, width), a ray is a tapering vertical bar. Found: 12 rays every 30 deg (not 8) and two rows of 60 ticks."],"facts":[{"fa":"حلقه‌ها (px)","en":"rings (px)","v":"75.2 · 177.5 · 245.3"},{"fa":"ضخامت حلقه‌ها (px)","en":"ring stroke (px)","v":"3.68 · 3.73 · 3.77"},{"fa":"خط دقیقه‌ی داخلی","en":"inner ticks","v":"2.25 / 7.42 px wide, r 243.5–268.0"},{"fa":"پرتو","en":"ray","v":"r 73.0–114.0 px, width 6.0 → 2.3 px"}]},{"id":"chords","file":"s05_lines.py","fig":"chords","fa":["وترها","حلقه‌ها و پرتوها که مخفی شدند، فقط خط‌های بلند می‌مانند. Hough، سپس «قوی‌ترین را پیدا کن، پاکش کن، تکرار کن» و کمترین‌مربعاتِ کل برای دقت زیرپیکسل. نتیجه: شش وتر از حلقه‌ی بیرونی (چهار خط ۲۶٫۶° و دو قطر ۴۵°) که دو تا از آن‌ها در رأسِ ۱۲ به یک مثلث توپُر می‌رسند."],"en":["Chords","With rings and rays masked, only long lines remain. Hough, then 'find the strongest, erase it, repeat', and total least squares for sub-pixel accuracy. Result: six chords of the outer ring (four at 26.6 deg and two diagonals at 45 deg), two of which meet in a solid triangle at 12."],"facts":[{"fa":"تعداد وتر","en":"chords","v":"6"},{"fa":"زاویه‌ها","en":"angles","v":"26.61° · 26.62° · 45.06° · 134.98° · 153.44° · 153.44°"},{"fa":"فاصله از مرکز (واحد)","en":"distance from centre (units)","v":"70.3 · 108.2 · 30.0 · 30.0 · 108.2 · 70.3"},{"fa":"خطای رگرسیون (px)","en":"fit rms (px)","v":"0.81 max"}]},{"id":"residual","file":"s06_residual.py","fig":"residual","fa":["باقی‌مانده","مدل پارامتریک (حلقه، خط، پرتو، وتر) را دوباره روی عکس رسم می‌کنیم و از جوهر کم می‌کنیم. آنچه می‌ماند دقیقاً چیزی است که هنوز توضیح داده نشده: اعداد، برچسب‌ها، آرم، پنجره‌ی تاریخ. ۷۰ تکه‌ی همبند، و شاخصِ «مدل ساختگی نیست»: ۹۱٪ پیکسل‌های مدل واقعاً جوهرند."],"en":["Residual","Re-render the parametric model on the photo and subtract it from the ink. What remains is exactly what is not yet explained: numerals, labels, logo, date window. 70 connected pieces, and a sanity check that the model is not hallucinating: 91 % of model pixels are real ink."],"facts":[{"fa":"تکه‌ها","en":"pieces","v":"70"},{"fa":"دقتِ مدل","en":"model precision","v":"0.907"}]},{"id":"text","file":"s07_text.py","fig":"text","fa":["اعداد و برچسب‌ها","قاعده‌ی چرخش اندازه‌گیری شد: برچسب‌های ۲۰ تا ۴۰ و اعداد ۴ تا ۸ وارونه می‌شوند تا خوانا بمانند (همبستگی رقم ۵: ۰٫۷۳–۰٫۸۱ با چرخش، ۰٫۵۲ بی‌چرخش). هر عدد با ۶× ریزنمونه‌برداری راست می‌شود، تکه‌های وابسته نگه داشته می‌شود و با potrace به منحنی بزیه می‌رسد. وترهایی که از عدد رد می‌شوند با آزمون «جوهر در دو سوی خط» پاک می‌شوند."],"en":["Numerals and labels","The rotation rule was measured: labels 20-40 and numerals 4-8 are flipped to stay readable (digit '5' correlates 0.73-0.81 flipped vs 0.52 unflipped). Each item is straightened at 6x, its components kept and traced to Bezier curves with potrace. Chords passing through a numeral are removed by a 'ink on both sides of the line' test."],"facts":[{"fa":"آیتم‌ها","en":"items","v":"25"},{"fa":"بازسازی‌شده (پنهان زیر عقربه)","en":"reconstructed (hidden under hands)","v":"min 10, hour 2, hour 10, logo swatch SWISS"},{"fa":"فونت","en":"typeface","v":"custom — no system font matched (best IoU 0.76)"}]},{"id":"details","file":"s07_text.py · build","fig":"details","fa":["پنجره‌ی تاریخ، آرم، مثلث رأس","پنجره‌ی تاریخ از پروفایل لبه‌ها اندازه‌گیری شد (۷۲٫۵×۵۵px، لبه‌ی آبی‌روشن، صفحه‌ی خاکستری گرادیانی، ارقام تیره). مثلث رأس بین دو وتر تا لبه‌ی بیرونی حلقه توپُر است."],"en":["Date window, logo, apex","The date window was measured from edge profiles (72.5 x 55 px, pale-blue rim, gradient grey plate, dark digits). The apex triangle is solid between the two chords down to the outer edge of the ring."],"facts":[{"fa":"پنجره (واحد)","en":"window (units)","v":"41.9 × 32.0"},{"fa":"رأس مثلث","en":"apex","v":"r = 157.2 u"}]},{"id":"body","file":"s09_body.py","fig":"body","fa":["بدنه و بند","استیلِ صیقلی از وجه‌های تخت ساخته شده که هر کدام تقریباً یک تُن دارند. تن‌ها با k-means روی روشنایی پیدا می‌شوند و هر آستانه یک ناحیه‌ی تو‌در‌تو می‌دهد؛ مرز ناحیه‌ها همان لبه‌ی وجه‌ها و شکاف حلقه‌های بند است. سیلوئت از ایزوخط زیرپیکسل کانال آلفا آمده."],"en":["Case and bracelet","Polished steel is made of flat facets of nearly constant tone. Tones come from k-means on luminance and each threshold gives a nested region; region boundaries ARE the facet edges and link gaps. The silhouette is the sub-pixel iso-line of the alpha channel."],"facts":[{"fa":"سطح‌های تن","en":"tone levels","v":"8"},{"fa":"حجم مسیرها","en":"path size","v":"171 KB"},{"fa":"سیلوئت IoU","en":"silhouette IoU","v":"0.9988"}]},{"id":"bezel","file":"s10_bezel.py","fig":"bezel","fa":["حلقه‌ی شیاردار","دندانه‌ها دوره‌ای‌اند: FFT زاویه‌ای ۱۲۰ دندانه (گام ۳٫۰۰۰°) می‌دهد. میانه‌ی ۱۲۰ تکه‌ی هم‌ترازشده یک دندانه‌ی دقیق می‌سازد. رنگ هر دندانه جدا ثبت شده تا الگوی براق‌شدنِ عکس با چرخش نور بچرخد."],"en":["Fluted bezel","The teeth are periodic: an angular FFT gives 120 teeth (pitch 3.000 deg). The median of 120 aligned patches gives one exact tooth. Each tooth's colour is stored so the photo's specular pattern can rotate with the light."],"facts":[{"fa":"دندانه","en":"teeth","v":"120"},{"fa":"شعاع (px)","en":"radius (px)","v":"353–378"},{"fa":"شیار","en":"groove","v":"2.38 px"},{"fa":"انحراف از شبکه‌ی ۳° (px)","en":"deviation from the 3° grid (px)","v":"1.07 rms"}]},{"id":"build","file":"s11_build.py","fig":"build","fa":["ساخت","همه‌ی عددها به واحد صفحه (۲۰۰ = شعاع) تبدیل و در assets/boreal-data.js و boreal-body.js نوشته می‌شود. سایت دقیقاً همین داده را می‌کشد؛ همان داده یک SVG ایستا هم می‌سازد."],"en":["Build","Every number is converted to dial units (200 = radius) and written to assets/boreal-data.js and boreal-body.js. The site draws exactly that data; the same data also yields a static SVG."],"facts":[{"fa":"اندازه‌ی داده","en":"data size","v":"≈55 KB + 171 KB"}]},{"id":"verify","file":"s12_verify.py","fig":"verify","fa":["راستی‌آزمایی","مدل برداری روی شبکه‌ی پیکسلی عکس رسم و با عکس مقایسه می‌شود. خطِ چاپ ~۱px چمفر دارد (کلِ پهنای خط ۲–۴px)؛ بدنه ۹۹٫۹٪ سیلوئت؛ عقربه‌ها ۴px انحراف از اختلاف‌منظرِ عکس (محور عقربه‌ها از مرکز صفحه ۳–۴px جدا بود و در مدل حذف شد)."],"en":["Verify","The vector model is rendered on the photo's pixel grid and compared. Print edges are within ~1 px chamfer (strokes are 2-4 px wide); the body matches 99.9 % of the silhouette; hands differ by ~4 px because the photo has parallax (the hands' axis was 3-4 px off the dial centre; the model removes it)."],"facts":[{"fa":"سیلوئت IoU","en":"silhouette IoU","v":"0.9988"},{"fa":"جوهر چاپ IoU","en":"print ink IoU","v":"0.7541"},{"fa":"چمفر لبه‌ها (px)","en":"edge chamfer (px)","v":"1.024 / 0.453"},{"fa":"خطای روشنایی فلز","en":"metal luminance MAE","v":"6.76 / 255"},{"fa":"عقربه‌ها IoU","en":"hands IoU","v":"0.5337"}]}]};
